// ja message catalog, typed `Partial<Record<MessageId, string>>`:
// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/ja-ko.md (the glossary is shared with
// the Raft mobile app's ja catalog). Product nouns are Japanese (エージェント,
// コンピューター, サーバー); brand forms (Raft, Raft Computer, Raft Desktop, …)
// stay Latin. Japanese has no count-plural distinction, so plural ICU uses a
// single `other` arm.

import type { MessageId } from "./en";

