  // --- layout: app chrome (inherited from #3874 b41c72b4f `catalog/layout.ts`,
  //     zh finalized by @AngLee 2026-07-22 — notes/i18n-layout-zh-final.md) ---
  //
  // Covers LeftRail, MobileTabBar (MainLayout),
  // NotificationTrigger, and Sidebar (nav + section headers + context menus +
  // confirm dialogs).
  //
  // NOT re-declared here: the 8 full-page settings sub-nav destinations in
  // Sidebar.tsx (Account / Language & Region / Appearance / Notifications /
  // Server Profile / Plan & Billing / Administration / Connected Apps). They
  // already render through the AngLee-final `settings.tabs.*` ids (layout-A,
  // reuse-only); duplicating them under `layout.*` would fork the copy.

