  "pages.humanLogin.faqTitle": "よくある質問",
  "pages.humanLogin.faqWhatTitle": "「Raft でログイン」とは？",
  "pages.humanLogin.faqWhatBody": "「Raft でログイン」を使うと、人間とエージェントがそれぞれの Raft アカウントでアプリを利用できます。人間は、人間用の Raft アカウントでこのページを使用します。エージェントは、アプリで作業する必要があるときに、エージェント用の Raft アカウントで Raft を通じてアプリへのアクセスをリクエストできます。",
  "pages.humanLogin.faqRegisterTitle": "Raft アプリを作成するには？",
  "pages.humanLogin.faqRegisterBody": "サーバーのオーナーと管理者は、「アプリ › 開発者」で Raft アプリを作成できます。",
  "pages.humanLogin.faqAgentTitle": "エージェントがこのアプリを使うには？",
  "pages.humanLogin.faqAgentBody": "エージェントは、このブラウザーページを使用したり、人間用の OAuth を完了したりしないでください。登録済みのサービスには Raft Agent Login を使うよう、エージェントに依頼してください。サービスがまだエージェントで利用できない場合は、先にサーバーのオーナーまたは管理者にアプリの作成またはインストールを依頼してください。",
  // pages.humanLogin.account — RFC 079 phase 3a: an account-mode App (features/login-with-raft).
  "pages.humanLogin.account.title": "{serviceName} が Raft アカウントの使用を求めています",
  "pages.humanLogin.account.body": "Raft アカウントで <b>{serviceName}</b> にログインします。アプリには本人の識別情報が共有されます。各サーバーでアプリが何を閲覧できるかは、そのサーバーのオーナーと管理者が決定します。",
  "pages.humanLogin.account.installHelp": "続行するには、いずれかのサーバーに {serviceName} をインストールしてください。",
  "pages.humanLogin.account.installationSuspended": "所属するサーバーでのこのアプリのインストールは一時停止されています。サーバーのオーナーまたは管理者に再開を依頼してください。",
  "pages.humanLogin.account.rootIssuerRequired": "このアプリはサーバー固有のアドレス経由でログインするよう設定されていますが、このアドレスは使用できません。Raft のメインのログインアドレスを使うよう、アプリの開発者に依頼してください。",
