  "agent.migration.hosted.attention.importStalled": "切り替えから長時間が経過しましたが、クラウドはまだワークスペースのファイルをインポートしていません。移行はまだ完了する可能性があり、Raft チームには通知済みです。サポートに問い合わせる場合は、移行 ID をお伝えください。",
  "agent.migration.hosted.attention.providerFailed": "クラウドでエージェントをセットアップできませんでした。移行はまだ完了する可能性があり、Raft チームには通知済みです。サポートに問い合わせる場合は、移行 ID をお伝えください。",
  "agent.migration.hosted.attention.agentDeleted": "エージェントはクラウド上で削除されており、クラウドではこのエージェントを再びセットアップできません。Raft チームには通知済みです。サポートに問い合わせる場合は、移行 ID をお伝えください。",
  "agent.migration.hosted.attention.providerMismatch": "クラウドで、Raft の想定とは異なるアカウントにこのエージェントが見つかりました。これは Raft 側の設定の問題です。Raft チームには通知済みです。サポートに問い合わせる場合は、移行 ID をお伝えください。",
  "agent.migration.hosted.agentNotCreated": "クラウドでエージェントがセットアップされなかったため、Raft はエージェントを変更せずに {source} に戻しました。もう一度お試しください。",
