  "migration.error.hostedMemoryUnimportable": "エージェントの MEMORY.md をクラウドに移行できません。ファイルが大きすぎるか、プレーンテキストではないか、クラウドに拒否されました。MEMORY.md をプレーンテキストに整理するようエージェントに依頼してから、もう一度お試しください。",
  "migration.error.notCancelable": "エージェントはすでにクラウドに移行したため、この移行はキャンセルできません。",
