  "migration.error.targetRuntimeDetectionIncomplete": "移行先のコンピューターで前回実行したランタイム検出が、{runtime} について完了しませんでした。コンピューターのページでランタイムを再スキャンしてから、もう一度お試しください。",
  "migration.error.alreadyInProgress": "このエージェントはすでに移行中です。完了するまで待ってから、もう一度お試しください。",
  "migration.error.proPlanRequired": "エージェントの移行には Pro プランが必要です。このサーバーを Pro にアップグレードしてから、もう一度お試しください。",
  "migration.error.transportNotProvisioned": "Raft はこれらのコンピューター間の安全な転送を準備できませんでした。両方のコンピューターがオンラインで最新の状態であることを確認してから、もう一度お試しください。",
  "migration.error.transportProvisionFailed": "Raft は転送を準備できませんでした。両方のコンピューターがオンラインであることを確認してから、もう一度お試しください。",
  "migration.error.transportLost": "転送中に 2 台のコンピューター間の接続が切断されました。両方のコンピューターがオンラインであることを確認してから、もう一度お試しください。",
  "migration.error.transportLostEvent": "転送中に 2 台のコンピューター間の接続が切断されました。",
  "migration.error.transportLostAt": "{time}、転送中に 2 台のコンピューター間の接続が切断されました。",
  "migration.error.transportLostRetryReady": "両方のコンピューターがオンラインになったため、再試行できます。",
  "migration.error.transportLostRetryOneOffline": "{computer} をオンラインにしてから、もう一度お試しください。",
  "migration.error.transportLostRetryBothOffline": "{source} と {target} をオンラインにしてから、もう一度お試しください。",
  "migration.error.transportLostRetryUnknown": "両方のコンピューターがオンラインであることを確認してから、もう一度お試しください。",
  "migration.error.entryCountLimitExceeded": "ワークスペース内のファイルとフォルダーが多すぎるため、移行できません。不要になったフォルダーを削除するか、.raftmigrateignore に追加するようエージェントに依頼してから、もう一度お試しください。",
  "migration.error.entryCountLimitExceededWithDetails": "ワークスペースにはファイルとフォルダーが {count, number} 件ありますが、移行できるのは最大 {limit, number} 件です。{paths, select, none {} other {大部分は {paths} にあります。}}不要になったフォルダーを削除するか、.raftmigrateignore に追加するようエージェントに依頼してから、もう一度お試しください。",
  "migration.error.workspaceAlreadyExists": "そのワークスペースがすでに存在するため、移行先のコンピューターにエージェントをインストールできませんでした。どちらのコピーが最新かを確認し、競合するワークスペースを移動またはバックアップしてから、もう一度お試しください。Raft が自動で削除することはありません。",
  "migration.error.workspaceCompleteOldCopy": "移行先のコンピューターで、このワークスペースの以前に完了したコピーが見つかったため、置き換える前に処理を停止しました。どちらのコピーが最新かを確認し、古いコピーを移動またはバックアップしてから、もう一度お試しください。Raft が自動で削除することはありません。",
  "migration.error.workspaceAlreadyExistsAt": "移行先のコンピューターの {path} にワークスペースがすでに存在するため、エージェントはインストールされませんでした。そのフォルダーの名前を変更するか移動してから（たとえば名前の末尾に .bak を付けるだけで十分です）、移行をもう一度開始してください。移動する前に、まだ必要なコピーではないことを確認してください。Raft がこのフォルダーを削除することはなく、移動してもそのコンピューター上に残ります。",
  "migration.error.workspaceCompleteOldCopyAt": "以前の移行で完了したこのワークスペースのコピーが移行先のコンピューターの {path} にあるため、Raft は置き換えずに処理を停止しました。そのフォルダーの名前を変更するか移動してから（たとえば名前の末尾に .old を付けるだけで十分です）、移行をもう一度開始してください。移動する前に、どちらのコピーが最新かを確認してください。Raft がこのフォルダーを削除することはなく、移動してもそのコンピューター上に残ります。",
  "migration.error.controlManifestInvalid": "移行元のコンピューターが生成した転送メタデータを、移行先のコンピューターで検証できませんでした。両方のコンピューターの Raft Computer をアップデートしてから、もう一度お試しください。",
  "migration.error.refInvalid": "移行の参照情報がないか、無効です。移行の状態を更新してから、もう一度お試しください。",
  "migration.error.revisionInvalid": "移行の状態が不完全です。更新してから、もう一度キャンセルをお試しください。",
  "migration.error.notFound": "この移行は利用できなくなりました。移行の状態を更新してください。",
  "migration.error.revisionStale": "この操作が完了する前に移行の状態が変わりました。更新して、もう一度お試しください。",
  "migration.error.concurrentUpdate": "移行の状態が同時に変更されました。更新して、もう一度お試しください。",
  "migration.error.cancelFailed": "Raft はキャンセルをリクエストできませんでした。移行の状態を更新して、もう一度お試しください。",
  "migration.error.startFailed": "移行を開始できませんでした。両方のコンピューターを確認して、もう一度お試しください。",
  "migration.error.statusFailed": "移行の状態を読み込めませんでした。更新して、もう一度お試しください。",
  "migration.error.objectStoreUnreachable": "いずれかのコンピューターが Raft の移行用ストレージに 5 分間接続できませんでした。そのコンピューターのネットワーク、プロキシ、ファイアウォールを確認してから、もう一度お試しください。",
  "migration.error.computerOwnerDeleted": "移行は停止しました。コンピューターの所有者の 1 人が Raft アカウントを削除しました。エージェントを別のコンピューターに移してください。",
  "migration.error.targetComputerDetached": "エージェントが移動する前に移行先のコンピューターの接続が解除されたため、この移行は停止しました。エージェントは元の場所に残っています。別のコンピューターを選択してください。",
  "migration.error.transferSummaryInvalid": "移行元のコンピューターで、この移行から除外したファイルを数えられませんでした。移行元のコンピューターの Raft Computer を最新バージョンに更新してから、もう一度お試しください。",
  "migration.error.userIgnoreWriteFailed": "除外するよう選んだパスを移行元のコンピューターに保存できなかったため、移行を停止しました。何も移動していません。",
